/* From Uiverse.io by Uncannypotato69  - Tags: animation, checkbox, neon, rotate, css, cool checkbox, multicolor, pride-month-special */
.__UIV_SCOPE__ .checkboxLabel {
  --rotate-offset: 45deg;
  --time-offset: 200ms;
  --translate-offset: 1rem;
  --delay: 250ms;
  --total-duration: calc(var(--time-offset) + var(--delay) * 7);

  position: relative;
  height: 3rem;
  aspect-ratio: 1/1;
  display: flex;
  justify-content: center;
  align-items: center;
  transition: transform var(--total-duration) ease-in-out;
}

.__UIV_SCOPE__ .bar {
  position: absolute;
  height: 3rem;
  width: 0.25rem;
  border-radius: 0.125rem;
  background-color: white;
  top: -50%;
  transform-origin: bottom;
  z-index: 0;
}

.__UIV_SCOPE__ #bar1 {
  rotate: calc(var(--rotate-offset));
  transition: all var(--time-offset) ease-in;
  transition-delay: calc(var(--delay) * 0);
  transform: translateY(calc(var(--translate-offset) * -1));
}
.__UIV_SCOPE__ #bar2 {
  rotate: calc(var(--rotate-offset) * 2);
  transition: all var(--time-offset) ease-in;
  transition-delay: calc(var(--delay) * 1);
  transform: translateY(calc(var(--translate-offset) * -1));
}
.__UIV_SCOPE__ #bar3 {
  rotate: calc(var(--rotate-offset) * 3);
  transition: all var(--time-offset) ease-in;
  transition-delay: calc(var(--delay) * 2);
  transform: translateY(calc(var(--translate-offset) * -1));
}
.__UIV_SCOPE__ #bar4 {
  rotate: calc(var(--rotate-offset) * 4);
  transition: all var(--time-offset) ease-in;
  transition-delay: calc(var(--delay) * 3);
  transform: translateY(calc(var(--translate-offset) * -1));
}
.__UIV_SCOPE__ #bar5 {
  rotate: calc(var(--rotate-offset) * 5);
  transition: all var(--time-offset) ease-in;
  transition-delay: calc(var(--delay) * 4);
  transform: translateY(calc(var(--translate-offset) * -1));
}
.__UIV_SCOPE__ #bar6 {
  rotate: calc(var(--rotate-offset) * 6);
  transition: all var(--time-offset) ease-in;
  transition-delay: calc(var(--delay) * 5);
  transform: translateY(calc(var(--translate-offset) * -1));
}
.__UIV_SCOPE__ #bar7 {
  rotate: calc(var(--rotate-offset) * 7);
  transition: all var(--time-offset) ease-in;
  transition-delay: calc(var(--delay) * 6);
  transform: translateY(calc(var(--translate-offset) * -1));
}
.__UIV_SCOPE__ #bar8 {
  rotate: calc(var(--rotate-offset) * 8);
  transition: all var(--time-offset) ease-in;
  transition-delay: calc(var(--delay) * 7);
  transform: translateY(calc(var(--translate-offset) * -1));
}

.__UIV_SCOPE__ #checkbox:checked ~ #bar1 {
  transform: translateY(0);
  background-color: #ffadad;
}
.__UIV_SCOPE__ #checkbox:checked ~ #bar2 {
  transform: translateY(0);
  background-color: #ffd6a5;
}
.__UIV_SCOPE__ #checkbox:checked ~ #bar3 {
  transform: translateY(0);
  background-color: #fdffb6;
}
.__UIV_SCOPE__ #checkbox:checked ~ #bar4 {
  transform: translateY(0);
  background-color: #caffbf;
}
.__UIV_SCOPE__ #checkbox:checked ~ #bar5 {
  transform: translateY(0);
  background-color: #9bf6ff;
}
.__UIV_SCOPE__ #checkbox:checked ~ #bar6 {
  transform: translateY(0);
  background-color: #a0c4ff;
}
.__UIV_SCOPE__ #checkbox:checked ~ #bar7 {
  transform: translateY(0);
  background-color: #bdb2ff;
}
.__UIV_SCOPE__ #checkbox:checked ~ #bar8 {
  transform: translateY(0);
  background-color: #ffc6ff;
}

.__UIV_SCOPE__ .cover {
  height: 4rem;
  aspect-ratio: 1/1;
  border-radius: 50%;
  background: #2a3439;
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
}

.__UIV_SCOPE__ .checkboxLabel:has(:checked) {
  transform: rotate(-360deg);
}

.__UIV_SCOPE__ .cover2 {
  height: 2rem;
  aspect-ratio: 1/1;
  border-radius: 50%;
  background: #91a3b0;
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  outline-width: 0.25rem;
  outline: solid;
  outline-color: #b2ffff;
}

.__UIV_SCOPE__ .inCover2 {
  height: 100%;
  aspect-ratio: 1/1;
  position: relative;
  border-radius: 50%;
  overflow: hidden;
}

.__UIV_SCOPE__ .inCover2 .rainbow {
  height: 100%;
  width: 100%;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  position: absolute;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
}

.__UIV_SCOPE__ .rainbow div {
  flex: 1;
  width: 100%;
}

.__UIV_SCOPE__ .rainbow div:nth-child(1) {
  background-color: #ffadad;
}
.__UIV_SCOPE__ .rainbow div:nth-child(2) {
  background-color: #ffd6a5;
}
.__UIV_SCOPE__ .rainbow div:nth-child(3) {
  background-color: #fdffb6;
}
.__UIV_SCOPE__ .rainbow div:nth-child(4) {
  background-color: #caffbf;
}
.__UIV_SCOPE__ .rainbow div:nth-child(5) {
  background-color: #9bf6ff;
}
.__UIV_SCOPE__ .rainbow div:nth-child(6) {
  background-color: #a0c4ff;
}
.__UIV_SCOPE__ .rainbow div:nth-child(7) {
  background-color: #bdb2ff;
}

.__UIV_SCOPE__ .nut {
  height: 0.3rem;
  aspect-ratio: 1/1;
  background-color: white;
  border-radius: 50%;
  position: absolute;
  z-index: 2;
  top: 0px;
  transform: translateY(-5px);
  transform-origin: 50% 500%;
}

.__UIV_SCOPE__ #nut1 {
  rotate: calc(var(--rotate-offset));
}
.__UIV_SCOPE__ #nut2 {
  rotate: calc(var(--rotate-offset) * 2);
}
.__UIV_SCOPE__ #nut3 {
  rotate: calc(var(--rotate-offset) * 3);
}
.__UIV_SCOPE__ #nut4 {
  rotate: calc(var(--rotate-offset) * 4);
}
.__UIV_SCOPE__ #nut5 {
  rotate: calc(var(--rotate-offset) * 5);
}
.__UIV_SCOPE__ #nut6 {
  rotate: calc(var(--rotate-offset) * 6);
}
.__UIV_SCOPE__ #nut7 {
  rotate: calc(var(--rotate-offset) * 7);
}
.__UIV_SCOPE__ #nut8 {
  rotate: calc(var(--rotate-offset) * 8);
}

.__UIV_SCOPE__ .lock {
  position: absolute;
  height: 1.5rem;
  aspect-ratio: 1/1;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  opacity: 0;
  transition: opacity 200ms ease-in;
  transition-delay: var(--total-duration);
}

.__UIV_SCOPE__ #checkbox:checked ~ .lock {
  opacity: 1;
}
